const CASTLE_SIGNS={"d0:11,8":["CASTELO DA BRASA. Chaves pequenas abrem portas comuns, e cada chave serve só neste castelo.","Dizem que no SUBSOLO, abaixo da Câmara Escura, repousa o BASTÃO DE BRASA."],"d7:12,8":["ANTESSALA DO TRONO. A porta grande só se abre com a CHAVE MESTRA, guardada na Torre Leste."],"d9:6,1":["A chama alcança o que a mão não alcança."],"c0:12,8":["CASTELO DAS MARÉS. As águas do castelo obedecem às COMPORTAS, a oeste.","Maré cheia: as plataformas flutuam. Maré vazante: os canais secam."],"c9:8,8":["COMPORTAS. Puxe a alavanca para baixar ou subir as águas de TODO o castelo."],"c7:11,9":["ANTESSALA DO TRONO. O Kraken dorme além da porta grande. A CHAVE MESTRA está na Torre do Farol."],"e0:11,8":["CASTELO DOS VENTOS. Suba a torre. Pisos rachados desabam sob seus pés: não pare em cima deles!"],"e14:12,9":["ANTESSALA DO NINHO. O Grifo espera além da porta grande."],"ss0:11,8":["TEMPLO DO SOL. \"Quem não enxerga longe não passa daqui.\"","Olhos de pedra vigiam as portas. Dizem que um ARCO repousa sob o templo."],"ss15:11,8":["O ESCORPIÃO DOURADO dorme além da porta grande. A CHAVE MESTRA está no Tesouro do Sol, a leste."],"sl0:11,8":["SANTUÁRIO DA FLORESTA. Raízes, copa e topo: suba a grande árvore.","Paredes muito rachadas não cedem à espada. Só uma explosão as derruba."],"sl14:11,8":["A FLOR DEVORADORA aguarda no topo. A CHAVE MESTRA brilha na Seiva Dourada, a leste."],"sb0:11,8":["SANTUÁRIO DA SOMBRA. Nem tudo que parece abismo é abismo.","Dizem que a LANTERNA DAS ALMAS, nas catacumbas, mostra o caminho invisível."],"sb9:11,8":["O ESPECTRO espera no trono. A CHAVE MESTRA está no Cofre das Almas, depois da Sala dos Ecos."],"sg0:11,8":["SANTUÁRIO DO GELO. A geleira desce fundo: três níveis até o coração.","Água demais para atravessar? Quem tiver o BASTÃO DE GELO faz o próprio caminho."],"sg11:11,8":["O YETI DAS NEVES espera além da porta grande. A CHAVE MESTRA repousa no Cofre Glacial, a leste."],"su0:11,8":["RUÍNAS DA LUA. Estacas antigas lacram as passagens.","Dizem que o MARTELO DA LUA está na arena a leste. Só ele afunda as estacas e quebra armaduras."],"su4:11,8":["PÁTIO DA LUA. O Cavaleiro da Lua guarda o altar ao norte. A CHAVE MESTRA está na Câmara da Lua Cheia."],"se0:11,8":["PICO ESTELAR. A última provação: cada andar pede tudo o que você aprendeu nos sete santuários.","Os olhos de pedra guardam a porta da torre."],"se15:12,8":["O GUARDIÃO ESTELAR espera no trono. A CHAVE MESTRA está no Cofre Estelar, no andar de baixo."],"ru0:11,8":["FORTALEZA SOMBRIA. O Rei Umbra prende a Princesa Lírian no trono, ao norte.","Nenhuma arma comum o fere... mas a magia dele pode ser devolvida."],"ru9:11,8":["O REI UMBRA aguarda além da porta grande. A CHAVE MESTRA está no Arsenal do Rei, a leste do Salão Negro."]};
